<template>
	<view class="container">
		<u-loading-page
		:loading="true" 
		v-if="load"
		fontSize="28rpx" />
		<block v-else>
		<view class="top-border"></view>
		<view class="inner">
			<view class="form">
				<view class="form-row">
					<text class="row-left">手机号</text>
					<view class="row-input">{{mobile}}</view>
				</view>
				<view class="form-row">
					<text class="row-left">真实姓名</text>
					<view class="row-input">
						<u-input
						    placeholder="请输入真实姓名"
							border="none"
							placeholderClass="placeholder30"
							v-model="form.realname"
						    clearable />
					</view>
				</view>
				<view class="form-row">
					<text class="row-left">开户银行</text>
					<view class="row-input">
						<u-input
						    placeholder="请输入开户银行"
							border="none"
							placeholderClass="placeholder30"
							v-model="form.bank_name"
						    clearable />
					</view>
				</view>
				<view class="form-row">
					<text class="row-left">银行卡号</text>
					<view class="row-input">
						<u-input
						    placeholder="请输入银行卡号"
							border="none"
							type="number"
							placeholderClass="placeholder30"
							v-model="form.bank_card"
						    clearable />
					</view>
				</view>
				<view class="form-row">
					<text class="row-left">支付宝</text>
					<view class="row-input">
						<u-input
						    placeholder="请输入支付宝"
							border="none"
							placeholderClass="placeholder30"
							v-model="form.zhifubao"
						    clearable />
					</view>
				</view>
				<view class="form-row" v-if="user_with_sms_enable==1">
					<text class="row-left">验证码</text>
					<view class="row-input">
						<u-input
						    placeholder="请输入验证码"
							border="none"
							type="number"
							maxlength="6"
							placeholderClass="placeholder30"
							v-model="form.code"
						    clearable />
					</view>
					<button type="default" size="mini" class="code-btn" :disabled="codeDisabled" @click="getCode">{{tips}}</button>
				</view>
			</view>
			<view class="submit">
				<button type="default" class="submit-btn" @click="submit"
					:disabled="submitDisabled">保存</button>
			</view>
		</view>
		</block>
		<u-code ref="uCode1" startText="获取验证码" :seconds="sms_time_out" @change="codeChange" change-text="Xs"
										@start="codeDisabled = true" @end="codeDisabled = false"></u-code>
	</view>
</template>

<script>
	var validate = require("@/components/validate/validate.js");
	var _this;
	export default {
		data() {
			return {
				form:{
					step:1,
					realname:'',
					bank_name:'',
					bank_card:'',
					zhifubao:'',
					code:'',
				},
				mobile:'',
				user_with_sms_enable:0,
				sms_time_out:60,
				isPassword:true,
				submitDisabled:false,
				tips:'获取验证码',
				codeDisabled:false,
				//从那个页面过来的1我的钱包界面
				from:0
			}
		},
		onLoad(e) {
			_this = this;
			if (e.from) {
				_this.from = e.from
			}
			_this.tijiao()
		},
		methods: {
			submit(){
				_this.form.step = 2
				_this.tijiao()
			},
			//提交
			async tijiao(){
				if (_this.form.step == 2) {
					let codeRule = {
						name: 'code',
						rules: ['require', 'integer', 'min:6'],
						errorMsg: {
							require: '请输入验证码',
							integer: '验证码只能为数字',
							min: '验证码为6位'
						}
					}
					var rule = [
					{
						name: 'realname',
						rules: ['require', 'chn'],
						errorMsg: {
							require: '请输入真实姓名',
							chn: '真实姓名只能为中文',
						}
					},{
						name: 'bank_name',
						rules: ['require', 'chn'],
						errorMsg: {
							require: '请输入开户银行',
							chn: '开户银行只能为中文',
						}
					}, {
						// 字段名
						name: 'bank_card',
						rules: ['require'],
						errorMsg: {
							require: '请输入银行卡号',
						}
					}, {
						// 字段名
						name: 'zhifubao',
						rules: ['require'],
						errorMsg: {
							require: '请输入支付宝',
						}
					}];
					if (this.user_with_sms_enable == 1) {
						rule.push(codeRule);
					}
					// 是否全部通过，返回Boolean
					let checked = validate.check(this.form, rule);
					if (!checked) {
						// 获取错误信息
						let err = validate.getError();
						uni.$u.toast(err[0])
						return;
					}
					_this.submitDisabled = true
					setTimeout(()=>{
						_this.submitDisabled = false
					},2000)
				}
				const data = await _this.$post('port/edit_user_bank',_this.form)
				if (data.code==200) {
					uni.$u.toast(data.msg,()=>{
						if(_this.from==1){
							_this.toNext(`/pages/my/my-wallet`,true)
						}else{
							_this.finish()
						}
					})
				}else if(data.code == -50){
					uni.$u.toast(data.msg,()=>{
						_this.finish()
					})
				}else if(data.code == -1){
					_this.mobile = data.result.mobile
					_this.sms_time_out = data.result.sms_time_out
					_this.user_with_sms_enable = data.result.user_with_sms_enable
					_this.form.realname = data.result.realname
					_this.form.bank_name = data.result.bank_name
					_this.form.bank_card = data.result.bank_card
					_this.form.zhifubao = data.result.zhifubao
					if (_this.load) {
						_this.load = false
					}
				}else{
					uni.$u.toast(data.msg)
				}
			},
			//获取验证码
			async getCode() {
				//单独验证使用
				// let check = validate.checkResult('mobile', this.phone);
				// if (!check) {
				// 	uni.$u.toast("手机号码格式有误")
				// 	return
				// }
				if (this.$refs.uCode1.canGetCode) {
					const params = {
						user_id: this.user_id,
						scene: 1
					}
					const data = await _this.$post('port/send_code',params)
					if (data.code == 200) {
						// 这里此提示会被this.start()方法中的提示覆盖
						uni.$u.toast('发送成功');
						// 通知验证码组件内部开始倒计时
						this.$refs.uCode1.start();
					} else {
						// 这里此提示会被this.start()方法中的提示覆盖
						uni.$u.toast(data.msg);
					}
				} else {
					uni.$u.toast('请倒计时结束后再发送');
				}
			},
			codeChange(text) {
				this.tips = text;
			}
		}
	}
</script>
<style lang="scss" scoped>
	@import "static/css/form.scss";
	.container {
		height: 100%;
		position: relative;
		.inner{
			padding: 0 20rpx;
			.form{
				padding: 0 20rpx;
				.form-row{
					padding: 0;
				}
			}
		}
	}
</style>